tool_args_30.text:
import json
import sys
import os

def collect_first_n_qas(squad_path, out_path, n):
    with open(squad_path, 'r') as f:
        data = json.load(f)

    total = 0
    new_data = []
    for article in data['data']:
        paragraphs = []
        for para in article['paragraphs']:
            qas_new = []
            for qa in para['qas']:
                if total < n:
                    qas_new.append(qa)
                    total += 1
                if total >= n:
                    break
            if qas_new:
                para_new = para.copy()
                para_new['qas'] = qas_new
                paragraphs.append(para_new)
            if total >= n:
                break
        if paragraphs:
            art_new = article.copy()
            art_new['paragraphs'] = paragraphs
            new_data.append(art_new)
        if total >= n:
            break

    with open(out_path, 'w') as f:
        json.dump({'data': new_data, 'version': data.get('version', '1.1')}, f)

if __name__ == "__main__":
    base_dir = os.path.dirname(__file__)
    collect_first_n_qas(os.path.join(base_dir, 'train-v1.1.json'), os.path.join(base_dir, 'gold_train.json'), 10)
    collect_first_n_qas(os.path.join(base_dir, 'dev-v1.1.json'), os.path.join(base_dir, 'gold_validation.json'), 10)

